/**
 * Katalog produk BisaBelanja per kategori.
 *
 * `hargaDasar` = perkiraan harga rak di supermarket (Rp). Harga yang
 * ditampilkan ke customer = hargaDasar + MARKUP_PER_ITEM.
 *
 * Catatan: harga di sini adalah estimasi acuan, bukan harga live dari toko.
 * Stok tiap gerai berbeda-beda, jadi daftar ini dipakai sebagai pilihan cepat
 * saat menyusun daftar belanja — bukan jaminan ketersediaan.
 */

/** Markup layanan default per item, dalam Rupiah. */
export const MARKUP_PER_ITEM = 1000

/**
 * Markup khusus per kategori. Kategori yang tidak terdaftar di sini memakai
 * MARKUP_PER_ITEM. Dipisah begini karena tiap kategori punya effort/risiko
 * belanja yang beda (mis. daging perlu penanganan dingin).
 */
export const MARKUP_BY_KATEGORI: Record<string, number> = {
  bumbu: 500,
  roti: 1000,
  sayur: 1000,
  snack: 1000,
  susu: 1200,
  buah: 1500,
  minuman: 1500,
  pokok: 2000,
  daging: 2000,
  seafood: 2500,
}

/** Markup yang berlaku untuk sebuah kategori. */
export function markupUntuk(kategoriId: string): number {
  return MARKUP_BY_KATEGORI[kategoriId] ?? MARKUP_PER_ITEM
}

export interface KatalogItem {
  id: string
  nama: string
  emoji: string
  image?: string
  /** Harga rak sebelum markup. */
  hargaDasar: number
  /** Harga rak promo sebelum markup. Ada = item sedang diskon. */
  hargaPromo?: number
  /** Satuan jual: kg, sisir, pcs, pack, cup. */
  satuan: string
  /** Ukuran/berat kemasan, mis. '450-500gram'. */
  ukuran?: string
  /** true = stok sedang kosong, tidak bisa ditambahkan ke keranjang. */
  habis?: boolean
  /** Pengelompokan di dalam halaman kategori. */
  grup: string
}

/** Item sedang diskon? */
export function adaPromo(item: KatalogItem): boolean {
  return typeof item.hargaPromo === 'number' && item.hargaPromo < item.hargaDasar
}

/**
 * Harga normal (sebelum diskon) yang ditampilkan ke customer.
 * Beri `kategoriId` supaya markup khusus kategori ikut terpakai.
 */
export function hargaNormal(item: KatalogItem, kategoriId?: string): number {
  return item.hargaDasar + (kategoriId ? markupUntuk(kategoriId) : MARKUP_PER_ITEM)
}

/**
 * Harga final yang benar-benar dibayar customer — pakai harga promo kalau ada.
 * Markup tetap ditambahkan di atas harga promo, karena biaya layanan tidak ikut
 * didiskon oleh gerai.
 */
export function hargaFinal(item: KatalogItem, kategoriId?: string): number {
  const markup = kategoriId ? markupUntuk(kategoriId) : MARKUP_PER_ITEM
  return (adaPromo(item) ? item.hargaPromo! : item.hargaDasar) + markup
}

